#include <format>
#include <iostream>
#include <memory>
#include <string_view>
#include <utility>

class Planner {
 public:
  virtual ~Planner() = default;
  [[nodiscard]] virtual std::string_view name() const = 0;
};

class GridPlanner final : public Planner {
 public:
  ~GridPlanner() override { std::cout << "grid planner destroyed\n"; }
  [[nodiscard]] std::string_view name() const override { return "grid"; }
};

class LatticePlanner final : public Planner {
 public:
  ~LatticePlanner() override { std::cout << "lattice planner destroyed\n"; }
  [[nodiscard]] std::string_view name() const override { return "lattice"; }
};

enum class PlannerKind { grid, lattice };

// The factory picks the class; the caller becomes the only owner.
[[nodiscard]] std::unique_ptr<Planner> make_planner(PlannerKind kind) {
  if (kind == PlannerKind::grid) return std::make_unique<GridPlanner>();
  return std::make_unique<LatticePlanner>();
}

class Robot {
 public:
  explicit Robot(std::unique_ptr<Planner> planner) : planner_(std::move(planner)) {}
  [[nodiscard]] std::string_view planner_name() const { return planner_->name(); }

 private:
  std::unique_ptr<Planner> planner_;
};

int main() {
  std::unique_ptr<Planner> planner = make_planner(PlannerKind::lattice);
  const Robot robot(std::move(planner));
  std::cout << std::format("robot plans with {}; the local pointer is {}\n", robot.planner_name(),
                           planner ? "set" : "empty");
  std::cout << std::format("unique_ptr: {} bytes, raw pointer: {} bytes\n", sizeof(planner), sizeof(Planner*));
}

