#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <memory>
#include <vector>

struct Frame {
  int id = 0;
  std::vector<std::uint8_t> pixels;
};

struct PoolSize {
  int frames = 0;
  int pixels_per_frame = 0;
};

class FramePool {
 public:
  // Called by a Lease's destructor for a non-null frame: returns the frame instead of deleting it.
  struct ReturnToPool {
    FramePool* pool = nullptr;
    void operator()(Frame* frame) const noexcept { pool->give_back(frame); }
  };
  using Lease = std::unique_ptr<Frame, ReturnToPool>;

  explicit FramePool(PoolSize size) : frames_(size.frames) {
    free_.reserve(frames_.size());  // room for every frame, so give_back never allocates
    int next_id = 0;
    for (Frame& frame : frames_) {
      frame.id = next_id++;
      frame.pixels.resize(size.pixels_per_frame);
      free_.push_back(&frame);
    }
  }
  // Leases hold this pool's address and point into frames_, so the pool stays where it is.
  FramePool(const FramePool&) = delete;
  FramePool& operator=(const FramePool&) = delete;
  FramePool(FramePool&&) = delete;
  FramePool& operator=(FramePool&&) = delete;

  [[nodiscard]] Lease acquire() {
    if (free_.empty()) return Lease(nullptr, ReturnToPool{this});
    Frame* frame = free_.back();
    free_.pop_back();
    return Lease(frame, ReturnToPool{this});
  }
  [[nodiscard]] std::ptrdiff_t free_frames() const { return std::ssize(free_); }

 private:
  void give_back(Frame* frame) noexcept { free_.push_back(frame); }

  std::vector<Frame> frames_;
  std::vector<Frame*> free_;
};

int main() {
  FramePool pool({.frames = 2, .pixels_per_frame = 640 * 480});
  FramePool::Lease first = pool.acquire();
  FramePool::Lease second = pool.acquire();
  const FramePool::Lease third = pool.acquire();
  std::cout << std::format("lent frames {} and {}; third request empty: {}\n", first->id, second->id,
                           third ? "no" : "yes");

  first.reset();  // the deleter returns frame 1 to the pool
  const FramePool::Lease again = pool.acquire();
  std::cout << std::format("frame 1 returned; the next request gets frame {}\n", again->id);

  std::vector<FramePool::Lease> encoder_queue;
  encoder_queue.push_back(std::move(second));
  std::cout << std::format("frame 0 queued for the encoder; free frames: {}\n", pool.free_frames());
  encoder_queue.clear();
  std::cout << std::format("encoder queue cleared; free frames: {}\n", pool.free_frames());

  std::cout << std::format("lease: {} bytes, plain unique_ptr: {} bytes\n", sizeof(FramePool::Lease),
                           sizeof(std::unique_ptr<Frame>));
}

#include <format>
#include <iostream>
#include <memory>
#include <string>
#include <utility>

class Map {
 public:
  explicit Map(std::string name) : name_(std::move(name)) {}
  ~Map() { std::cout << std::format("{} map freed\n", name_); }

 private:
  std::string name_;
};

int main() {
  auto map = std::make_shared<const Map>("warehouse");
  std::cout << std::format("one owner: use_count {}\n", map.use_count());

  auto planner = map;
  auto localiser = map;
  std::cout << std::format("planner and localiser share it: use_count {}\n", map.use_count());

  const std::weak_ptr<const Map> watcher = map;
  std::cout << std::format("a watcher doesn't count: use_count {}\n", map.use_count());

  map.reset();
  planner.reset();
  std::cout << std::format("two owners gone: use_count {}, watcher expired: {}\n", watcher.use_count(),
                           watcher.expired() ? "yes" : "no");

  localiser.reset();
  std::cout << std::format("last owner gone: watcher expired: {}\n", watcher.expired() ? "yes" : "no");
}

