int allocations = 0;  // global only because a replacement operator new has to be global

void* operator new(std::size_t size) {
  ++allocations;
  if (void* p = std::malloc(size)) return p;
  throw std::bad_alloc();
}
void operator delete(void* p) noexcept { std::free(p); }
void operator delete(void* p, std::size_t) noexcept { std::free(p); }

struct Scan {
  std::array<float, 360> ranges{};
};

template <typename MakeOwner>
void count_allocations(std::string_view label, MakeOwner make_owner) {
  const int before = allocations;
  { const auto owner = make_owner(); }
  const int used = allocations - before;
  std::cout << std::format("{}: {} allocation{}\n", label, used, used == 1 ? "" : "s");
}

int main() {
  count_allocations("make_unique", [] { return std::make_unique<Scan>(); });
  count_allocations("make_shared", [] { return std::make_shared<Scan>(); });
  count_allocations("shared_ptr from make_unique", [] { return std::shared_ptr<Scan>(std::make_unique<Scan>()); });
}

#include <format>
#include <functional>
#include <iostream>
#include <memory>
#include <utility>

class Timer {
 public:
  explicit Timer(std::function<void()> callback) : callback_(std::move(callback)) {}
  void fire() const { callback_(); }

 private:
  std::function<void()> callback_;
};

class Controller {
 public:
  ~Controller() { std::cout << "controller destroyed\n"; }
  void tick() { std::cout << std::format("tick {}\n", ++ticks_); }
  void set_timer(std::shared_ptr<Timer> timer) { timer_ = std::move(timer); }
  [[nodiscard]] std::shared_ptr<Timer> timer() const { return timer_; }

 private:
  std::shared_ptr<Timer> timer_;
  int ticks_ = 0;
};

// controller -> timer -> callback -> controller: the callback owns a share of its own owner.
[[nodiscard]] std::weak_ptr<Controller> start_with_owning_callback() {
  auto controller = std::make_shared<Controller>();
  controller->set_timer(std::make_shared<Timer>([controller] { controller->tick(); }));
  controller->timer()->fire();
  return controller;
}

// The callback only watches the controller, and skips the tick once the controller is gone.
[[nodiscard]] std::weak_ptr<Controller> start_with_watching_callback() {
  auto controller = std::make_shared<Controller>();
  controller->set_timer(std::make_shared<Timer>([watched = std::weak_ptr(controller)] {
    if (const auto alive = watched.lock()) alive->tick();
  }));
  controller->timer()->fire();
  return controller;
}

int main() {
  const std::weak_ptr<Controller> first = start_with_owning_callback();
  std::cout << std::format("owning callback: controller {} after its owner returned, use_count {}\n",
                           first.expired() ? "destroyed" : "still alive", first.use_count());

  const std::weak_ptr<Controller> second = start_with_watching_callback();
  std::cout << std::format("watching callback: controller {} after its owner returned\n",
                           second.expired() ? "destroyed" : "still alive");

  // Only the cycle holds the first controller now. Breaking it by hand frees it.
  if (const auto stuck = first.lock()) stuck->set_timer(nullptr);
}

#include <cstdint>
