#include <unordered_map>
#include <utility>
#include <vector>

struct Map {
  std::string name;
  std::vector<std::uint8_t> cells;
};

class MapCache {
 public:
  using Loader = std::function<Map(std::string_view)>;
  explicit MapCache(Loader load) : load_(std::move(load)) {}

  [[nodiscard]] std::shared_ptr<const Map> get(std::string_view name) {
    std::weak_ptr<const Map>& slot = maps_[std::string(name)];
    if (auto map = slot.lock()) return map;  // someone still holds it
    auto map = std::make_shared<const Map>(load_(name));
    slot = map;
    return map;
  }

 private:
  Loader load_;
  std::unordered_map<std::string, std::weak_ptr<const Map>> maps_;
};

int main() {
  int loads = 0;
  MapCache cache([&loads](std::string_view name) {
    ++loads;
    return Map{.name = std::string(name), .cells = std::vector<std::uint8_t>(1000)};
  });

  {
    const auto for_planner = cache.get("warehouse");
    const auto for_localiser = cache.get("warehouse");
    std::cout << std::format("same map: {}, use_count {}, loads {}\n",
                             for_planner == for_localiser ? "yes" : "no", for_planner.use_count(), loads);
  }
  const auto later = cache.get("warehouse");
  std::cout << std::format("after both let go, the next request loads again: loads {}\n", loads);
  const auto other = cache.get("loading dock");
  std::cout << std::format("another map: loads {}\n", loads);
}

