#include <format>
#include <functional>
#include <iostream>
#include <memory>
#include <utility>
#include <vector>

class Dispatcher {
 public:
  void post(std::function<void()> job) { jobs_.push_back(std::move(job)); }
  void run_all() {
    for (const auto& job : jobs_) job();
    jobs_.clear();
  }

 private:
  std::vector<std::function<void()>> jobs_;
};

class Session : public std::enable_shared_from_this<Session> {
 public:
  ~Session() { std::cout << "session destroyed\n"; }

  // The queued job owns a share of the session, so the session lives until the job has run.
  void request_scan(Dispatcher& dispatcher) {
    dispatcher.post([self = shared_from_this()] { self->on_scan(); });
  }

 private:
  void on_scan() const { std::cout << "scan received\n"; }
};

int main() {
  Dispatcher dispatcher;
  {
    const auto session = std::make_shared<Session>();
    session->request_scan(dispatcher);
    std::cout << std::format("the pending job holds a share: use_count {}\n", session.use_count());
  }
  std::cout << "the caller has let go\n";
  dispatcher.run_all();

  Session on_stack;  // owned by no shared_ptr
  try {
    on_stack.request_scan(dispatcher);
  } catch (const std::bad_weak_ptr& e) {
    std::cout << std::format("on the stack: {}\n", e.what());
  }
}

#include <format>
#include <iostream>
#include <memory>

class Session : public std::enable_shared_from_this<Session> {
  struct Token {
    explicit Token() = default;
  };

 public:
  // Public, so make_shared can call it, but only Session can make the Token it needs.
  explicit Session(Token /*only_from_create*/) {}
  // A copy would be a Session that no shared_ptr owns, so copies and moves are deleted too.
  Session(const Session&) = delete;
  Session& operator=(const Session&) = delete;
  Session(Session&&) = delete;
  Session& operator=(Session&&) = delete;
  ~Session() = default;
  [[nodiscard]] static std::shared_ptr<Session> create() { return std::make_shared<Session>(Token{}); }
};

int main() {
  const auto session = Session::create();
  const auto self = session->shared_from_this();
  std::cout << std::format("made by create(); shared_from_this shares its count: use_count {}\n",
                           session.use_count());
}

