#include <format>
#include <iostream>
#include <memory>
#include <utility>
#include <vector>

struct Map {
  std::vector<int> cells;
};

class Navigator {
 public:
  explicit Navigator(std::shared_ptr<const Map> map) : map_(std::move(map)) {}
  void step() { plan(*map_); }  // lends the map without holding a share of it

 private:
  void plan(const Map& map) {
    reload();  // replaces map_, the only owner of the old map
    std::cout << std::format("planning over {} cells\n", map.cells.size());
  }
  void reload() { map_ = std::make_shared<const Map>(Map{.cells = std::vector<int>(8)}); }

  std::shared_ptr<const Map> map_;
};

int main() {
  Navigator navigator(std::make_shared<const Map>(Map{.cells = std::vector<int>(4)}));
  navigator.step();
}
